// Leaky: listeners and a cache that keep every widget alive forever
const cache = new Map();
function mountLeaky(widget, target) {
  cache.set(widget, { big: new Array(1e5).fill(widget.id) });
  target.addEventListener("tick", () => widget.render());
}

// Fixed: weak cache + listeners removed via an AbortController
const meta = new WeakMap();                 // entry dies with its key
function mount(widget, target) {
  meta.set(widget, { big: new Array(1e5).fill(widget.id) });
  const ac = new AbortController();
  target.addEventListener("tick", () => widget.render(), { signal: ac.signal });
  return () => ac.abort();                  // unmount: removes the listener
}

